#include <bits/stdc++.h>
using namespace std;
using ll=long long;

int main() {
	
	ll t;
	cin>>t;
	while(t--)
	{
	    ll n,c;
	    cin>>n>>c;
	    vector<ll>r(c),covered(c);
	    for(ll i=0;i<c;i++)
	    {
	        cin>>r[i];
	        
	    }
	    if( c== n)
	    {
	        cout<<0<<"\n";
	        continue;
	    }
	    sort(r.begin(),r.end());
	    ll inMov=min(r[0]-1,n-r[c-1]);
	    ll ans=inMov*2;
	    //cout<<ans<<"\n";
	    for(ll i=0;i<c;i++)
	    {
	        if((r[0] - 1) <= (n - r[c-1] ))
	        {
	            covered[i]=r[i]-inMov;
	            
	        }
	        else
	        {
	            covered[i]=r[i]+inMov;
	        }
	    }
	    
	    ll maxi=0;
	    if((r[0] - 1) <= (n - r[c-1]))
	    
	    {
	        for(ll i=0;i<c;i++)
    	    {
    	        if(i!=c-1 && covered[i+1]>=1 && covered[i+1]<=n)
    	        {
    	            maxi=max( (abs(covered[i+1]-1 - r[i])) , maxi);
    	        }
    	        else
    	        {
    	            maxi=max( abs(n - r[i]),maxi);
    	        }
    	    }
    	    
	    }
	    else
	    {
	        for(ll i=0;i<c;i++)
	        {
	            if(i==0)
	            {
	                maxi=max(abs(r[0]-1) , maxi);
	            }
	            else if(covered[i-1]<=n && covered[i+1]>=1)
	            {
	                maxi= max(abs(r[i]-covered[i-1]-1) , maxi);
	            }
	        }
	    }
	    ans+=maxi;
	    cout<<ans<<"\n";
	    
	}

}
